149	  return (
150	    <ZimmCountryLanguageMismatch
151	      variant="language"
152	      isOpen={languagePromptState.isOpen}
153	      onDismiss={handleDismiss}
154	      inCountry={targetConfig.countryPhrase}
155	      inLanguage={targetConfig.languagePhrase}
156	      inCurrentLanguage={currentConfig?.languagePhrase ?? ''}
157	      target={languagePromptState.targetLanguage}
158	      onSwitchLanguage={handleSwitchLanguage}
159	    />
160	  );
161	};
162	
163	export default ZimmLanguagePrompt;
