1	import React from 'react';
2	import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
3	import { render, screen } from '@testing-library/react';
4	import userEvent from '@testing-library/user-event';
5	import { ZimmLanguagePrompt, EU_LANGUAGE_CONFIG } from './index';
6	import { shouldShowLanguagePrompt, SUPPORTED_EU_LANGUAGES } from 'app/utils/shouldShowLanguagePrompt';
7	import { getRegionPrefCookie, setRegionPrefCookie } from 'app/utils/regionPrefCookie';
8	import { crossSiteUrl } from 'app/utils/crossSiteUrl';
9	
10	// ZimmCountryLanguageMismatch pulls in ZimmButton -> ZimmIcon -> the base SFCC icons barrel,
11	// which throws at module-evaluation time under Vitest (testing.md's documented "ZimmIcon throws
12	// under Vitest" gap). Mocked wholesale here — its own render-branch/copy/callback-wiring contract
13	// already has its own suite (index.test.tsx, SFCC-831); this suite only needs to prove what THIS
14	// container passes it and when its callbacks fire. Spy + interactive stub, same technique
15	// _app/index.test.tsx already uses for drawerMenuSpy.
16	const zimmCountryLanguageMismatchSpy = vi.fn();
17	vi.mock('app/components/ui-kits/organisms/zimmCountryLanguageMismatch', () => ({
18	  ZimmCountryLanguageMismatch: (props: {
19	    isOpen: boolean;
20	    target: unknown;
21	    onSwitchLanguage: (target: unknown) => void;
22	    onDismiss: () => void;
23	  }) => {
24	    zimmCountryLanguageMismatchSpy(props);
25	    if (!props.isOpen) return null;
26	    return (
27	      <div data-testid="mock-prompt">
28	        <button onClick={() => props.onSwitchLanguage(props.target)}>mock-switch</button>
29	        <button onClick={() => props.onDismiss()}>mock-dismiss</button>
30	      </div>
31	    );
32	  },
33	}));
34	
35	// shouldShowLanguagePrompt has its own dedicated suite (11 tests, shouldShowLanguagePrompt.test.ts)
36	// proving its six branches — mock only the function here, per testing.md's guidance to "mock the
37	// hook/child component whose internals are proven elsewhere, and test only this component's own
38	// contract", so this suite controls the eligibility outcome directly rather than re-deriving it
39	// from real navigator/cookie state. SUPPORTED_EU_LANGUAGES is passed through real (importOriginal
40	// + spread) so the drift-guard test below exercises the actual exported array, not a hand-copied
41	// duplicate of it.
42	vi.mock('app/utils/shouldShowLanguagePrompt', async (importOriginal) => {
43	  const actual = await importOriginal<typeof import('app/utils/shouldShowLanguagePrompt')>();
44	  return { ...actual, shouldShowLanguagePrompt: vi.fn() };
45	});
46	
47	// regionPrefCookie's own parse/serialise/get/set logic has its own dedicated suite — mocked here
48	// as plain spies so this suite can assert exactly what this container writes and, critically,
49	// when, without needing a real document.cookie round-trip.
50	vi.mock('app/utils/regionPrefCookie', () => ({
51	  getRegionPrefCookie: vi.fn(() => ({})),
52	  setRegionPrefCookie: vi.fn(),
53	}));
54	
55	// crossSiteUrl's own path/query-stripping logic has its own dedicated suite — mocked to a fixed
56	// return value so this suite can assert the container calls it with the right alias/locale/
57	// buildUrl and assigns the *result* to window.location.href, without exercising real
58	// getParamsFromPath/getRouterBasePath machinery against a real window.location.
59	vi.mock('app/utils/crossSiteUrl', () => ({
60	  crossSiteUrl: vi.fn(() => '/mock-target-url'),
61	}));
62	
63	const mockShouldShowLanguagePrompt = vi.mocked(shouldShowLanguagePrompt);
64	const mockGetRegionPrefCookie = vi.mocked(getRegionPrefCookie);
65	const mockSetRegionPrefCookie = vi.mocked(setRegionPrefCookie);
66	const mockCrossSiteUrl = vi.mocked(crossSiteUrl);
67	
68	const SITE = { id: 'ZimmermannEUit', sfccSiteId: 'ZimmermannEU' };
69	const LOCALE = { id: 'it' };
70	const BUILD_URL = vi.fn((path: string) => path);
71	
72	/**
73	 * Stubs the `location` global with a `href` setter spy — the same technique already established
74	 * in this codebase for asserting on `window.location.href` navigation
75	 * (zimmColourSwatch/index.test.tsx's `vi.stubGlobal('location', locationMock)`), extended with a
76	 * setter so the *moment* of assignment is independently orderable via
77	 * `mock.invocationCallOrder`, which is what the cookie-before-navigate tests below rely on.
78	 */
79	function stubLocationHref(): ReturnType<typeof vi.fn> {
80	  const setHrefSpy = vi.fn();
81	  vi.stubGlobal('location', {
82	    set href(value: string) {
83	      setHrefSpy(value);
84	    },
85	  });
86	  return setHrefSpy;
87	}
88	
89	describe('ZimmLanguagePrompt', () => {
90	  beforeEach(() => {
91	    vi.clearAllMocks();
92	    mockGetRegionPrefCookie.mockReturnValue({});
93	    mockCrossSiteUrl.mockReturnValue('/mock-target-url');
94	  });
95	
96	  afterEach(() => {
97	    vi.unstubAllGlobals();
98	  });
99	
100	  test('renders nothing when shouldShowLanguagePrompt says no', () => {
101	    mockShouldShowLanguagePrompt.mockReturnValue({ show: false });
102	
103	    render(<ZimmLanguagePrompt site={SITE} locale={LOCALE} buildUrl={BUILD_URL} />);
104	
105	    expect(zimmCountryLanguageMismatchSpy).not.toHaveBeenCalled();
106	  });
107	
108	  test('wires site/locale/cookie/navigator into the eligibility predicate', () => {
109	    mockShouldShowLanguagePrompt.mockReturnValue({ show: false });
110	    mockGetRegionPrefCookie.mockReturnValue({ languageSuppressedAt: 111 });
111	
112	    render(<ZimmLanguagePrompt site={SITE} locale={LOCALE} buildUrl={BUILD_URL} />);
113	
114	    expect(mockShouldShowLanguagePrompt).toHaveBeenCalledTimes(1);
115	    const input = mockShouldShowLanguagePrompt.mock.calls[0][0];
116	    expect(input.sfccSiteId).toBe('ZimmermannEU');
117	    expect(input.currentLanguage).toBe('it');
118	    expect(input.suppressedAt).toBe(111);
119	    // Reference equality: the container must forward navigator.languages itself, not a copy.
120	    expect(input.browserLanguages).toBe(window.navigator.languages);
121	    expect(typeof input.now).toBe('number');
122	  });
123	
124	  describe('when eligible', () => {
125	    test('renders the real component with the Italian target resolved from the map', () => {
126	      mockShouldShowLanguagePrompt.mockReturnValue({ show: true, targetLanguage: 'it' });
127	
128	      render(
129	        <ZimmLanguagePrompt
130	          site={{ id: 'ZimmermannEUen', sfccSiteId: 'ZimmermannEU' }}
131	          locale={{ id: 'en-GB' }}
132	          buildUrl={BUILD_URL}
133	        />,
134	      );
135	
136	      expect(zimmCountryLanguageMismatchSpy).toHaveBeenCalledWith(
137	        expect.objectContaining({
138	          isOpen: true,
139	          variant: 'language',
140	          inCountry: 'in Italy',
141	          inLanguage: 'in Italian',
142	          inCurrentLanguage: 'in English',
143	          target: 'it',
144	        }),
145	      );
146	    });
147	
148	    test('renders the real component with the Spanish target resolved from the map (proves the lookup is not hardcoded to one case)', () => {
149	      mockShouldShowLanguagePrompt.mockReturnValue({ show: true, targetLanguage: 'es' });
150	
151	      render(
152	        <ZimmLanguagePrompt
153	          site={{ id: 'ZimmermannEUfr', sfccSiteId: 'ZimmermannEU' }}
154	          locale={{ id: 'fr' }}
155	          buildUrl={BUILD_URL}
156	        />,
157	      );
158	
159	      expect(zimmCountryLanguageMismatchSpy).toHaveBeenCalledWith(
160	        expect.objectContaining({
161	          inCountry: 'in Spain',
162	          inLanguage: 'in Spanish',
163	          inCurrentLanguage: 'in French',
164	          target: 'es',
165	        }),
166	      );
167	    });
168	  });
169	
170	  describe('onSwitchLanguage — cookie-before-navigate ordering (the whole point of this step)', () => {
171	    test('writes the suppression cookie before assigning window.location.href', async () => {
172	      mockShouldShowLanguagePrompt.mockReturnValue({ show: true, targetLanguage: 'fr' });
173	      const setHrefSpy = stubLocationHref();
174	
175	      render(<ZimmLanguagePrompt site={SITE} locale={LOCALE} buildUrl={BUILD_URL} />);
176	      await userEvent.click(screen.getByRole('button', { name: 'mock-switch' }));
177	
178	      expect(mockSetRegionPrefCookie).toHaveBeenCalledTimes(1);
179	      expect(setHrefSpy).toHaveBeenCalledTimes(1);
180	      expect(setHrefSpy).toHaveBeenCalledWith('/mock-target-url');
181	
