import React from 'react';
import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ZimmLanguagePrompt, EU_LANGUAGE_CONFIG } from './index';
import { shouldShowLanguagePrompt, SUPPORTED_EU_LANGUAGES } from 'app/utils/shouldShowLanguagePrompt';
import { getRegionPrefCookie, setRegionPrefCookie } from 'app/utils/regionPrefCookie';
import { crossSiteUrl } from 'app/utils/crossSiteUrl';

// ZimmCountryLanguageMismatch pulls in ZimmButton -> ZimmIcon -> the base SFCC icons barrel,
// which throws at module-evaluation time under Vitest (testing.md's documented "ZimmIcon throws
// under Vitest" gap). Mocked wholesale here — its own render-branch/copy/callback-wiring contract
// already has its own suite (index.test.tsx, SFCC-831); this suite only needs to prove what THIS
// container passes it and when its callbacks fire. Spy + interactive stub, same technique
// _app/index.test.tsx already uses for drawerMenuSpy.
const zimmCountryLanguageMismatchSpy = vi.fn();
vi.mock('app/components/ui-kits/organisms/zimmCountryLanguageMismatch', () => ({
  ZimmCountryLanguageMismatch: (props: {
    isOpen: boolean;
    target: unknown;
    onSwitchLanguage: (target: unknown) => void;
    onDismiss: () => void;
  }) => {
    zimmCountryLanguageMismatchSpy(props);
    if (!props.isOpen) return null;
    return (
      <div data-testid="mock-prompt">
        <button onClick={() => props.onSwitchLanguage(props.target)}>mock-switch</button>
        <button onClick={() => props.onDismiss()}>mock-dismiss</button>
      </div>
    );
  },
}));

// shouldShowLanguagePrompt has its own dedicated suite (11 tests, shouldShowLanguagePrompt.test.ts)
// proving its six branches — mock only the function here, per testing.md's guidance to "mock the
// hook/child component whose internals are proven elsewhere, and test only this component's own
// contract", so this suite controls the eligibility outcome directly rather than re-deriving it
// from real navigator/cookie state. SUPPORTED_EU_LANGUAGES is passed through real (importOriginal
// + spread) so the drift-guard test below exercises the actual exported array, not a hand-copied
// duplicate of it.
vi.mock('app/utils/shouldShowLanguagePrompt', async (importOriginal) => {
  const actual = await importOriginal<typeof import('app/utils/shouldShowLanguagePrompt')>();
  return { ...actual, shouldShowLanguagePrompt: vi.fn() };
});

// regionPrefCookie's own parse/serialise/get/set logic has its own dedicated suite — mocked here
// as plain spies so this suite can assert exactly what this container writes and, critically,
// when, without needing a real document.cookie round-trip.
vi.mock('app/utils/regionPrefCookie', () => ({
  getRegionPrefCookie: vi.fn(() => ({})),
  setRegionPrefCookie: vi.fn(),
}));

// crossSiteUrl's own path/query-stripping logic has its own dedicated suite — mocked to a fixed
// return value so this suite can assert the container calls it with the right alias/locale/
// buildUrl and assigns the *result* to window.location.href, without exercising real
// getParamsFromPath/getRouterBasePath machinery against a real window.location.
vi.mock('app/utils/crossSiteUrl', () => ({
  crossSiteUrl: vi.fn(() => '/mock-target-url'),
}));

const mockShouldShowLanguagePrompt = vi.mocked(shouldShowLanguagePrompt);
const mockGetRegionPrefCookie = vi.mocked(getRegionPrefCookie);
const mockSetRegionPrefCookie = vi.mocked(setRegionPrefCookie);
const mockCrossSiteUrl = vi.mocked(crossSiteUrl);

const SITE = { id: 'ZimmermannEUit', sfccSiteId: 'ZimmermannEU' };
const LOCALE = { id: 'it' };
const BUILD_URL = vi.fn((path: string) => path);

/**
 * Stubs the `location` global with a `href` setter spy — the same technique already established
 * in this codebase for asserting on `window.location.href` navigation
 * (zimmColourSwatch/index.test.tsx's `vi.stubGlobal('location', locationMock)`), extended with a
 * setter so the *moment* of assignment is independently orderable via
 * `mock.invocationCallOrder`, which is what the cookie-before-navigate tests below rely on.
 */
function stubLocationHref(): ReturnType<typeof vi.fn> {
  const setHrefSpy = vi.fn();
  vi.stubGlobal('location', {
    set href(value: string) {
      setHrefSpy(value);
    },
  });
  return setHrefSpy;
}

describe('ZimmLanguagePrompt', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockGetRegionPrefCookie.mockReturnValue({});
    mockCrossSiteUrl.mockReturnValue('/mock-target-url');
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  test('renders nothing when shouldShowLanguagePrompt says no', () => {
    mockShouldShowLanguagePrompt.mockReturnValue({ show: false });

    render(<ZimmLanguagePrompt site={SITE} locale={LOCALE} buildUrl={BUILD_URL} />);

    expect(zimmCountryLanguageMismatchSpy).not.toHaveBeenCalled();
  });

  test('wires site/locale/cookie/navigator into the eligibility predicate', () => {
    mockShouldShowLanguagePrompt.mockReturnValue({ show: false });
    mockGetRegionPrefCookie.mockReturnValue({ languageSuppressedAt: 111 });

    render(<ZimmLanguagePrompt site={SITE} locale={LOCALE} buildUrl={BUILD_URL} />);

    expect(mockShouldShowLanguagePrompt).toHaveBeenCalledTimes(1);
    const input = mockShouldShowLanguagePrompt.mock.calls[0][0];
    expect(input.sfccSiteId).toBe('ZimmermannEU');
    expect(input.currentLanguage).toBe('it');
    expect(input.suppressedAt).toBe(111);
    // Reference equality: the container must forward navigator.languages itself, not a copy.
    expect(input.browserLanguages).toBe(window.navigator.languages);
    expect(typeof input.now).toBe('number');
  });

  describe('when eligible', () => {
    test('renders the real component with the Italian target resolved from the map', () => {
      mockShouldShowLanguagePrompt.mockReturnValue({ show: true, targetLanguage: 'it' });

      render(
        <ZimmLanguagePrompt
          site={{ id: 'ZimmermannEUen', sfccSiteId: 'ZimmermannEU' }}
          locale={{ id: 'en-GB' }}
          buildUrl={BUILD_URL}
        />,
      );

      expect(zimmCountryLanguageMismatchSpy).toHaveBeenCalledWith(
        expect.objectContaining({
          isOpen: true,
          variant: 'language',
          inCountry: 'in Italy',
          inLanguage: 'in Italian',
          inCurrentLanguage: 'in English',
          target: 'it',
        }),
      );
    });

    test('renders the real component with the Spanish target resolved from the map (proves the lookup is not hardcoded to one case)', () => {
      mockShouldShowLanguagePrompt.mockReturnValue({ show: true, targetLanguage: 'es' });

      render(
        <ZimmLanguagePrompt
          site={{ id: 'ZimmermannEUfr', sfccSiteId: 'ZimmermannEU' }}
          locale={{ id: 'fr' }}
          buildUrl={BUILD_URL}
        />,
      );

      expect(zimmCountryLanguageMismatchSpy).toHaveBeenCalledWith(
        expect.objectContaining({
          inCountry: 'in Spain',
          inLanguage: 'in Spanish',
          inCurrentLanguage: 'in French',
          target: 'es',
        }),
      );
    });
  });

  describe('onSwitchLanguage — cookie-before-navigate ordering (the whole point of this step)', () => {
    test('writes the suppression cookie before assigning window.location.href', async () => {
      mockShouldShowLanguagePrompt.mockReturnValue({ show: true, targetLanguage: 'fr' });
      const setHrefSpy = stubLocationHref();

      render(<ZimmLanguagePrompt site={SITE} locale={LOCALE} buildUrl={BUILD_URL} />);
      await userEvent.click(screen.getByRole('button', { name: 'mock-switch' }));

      expect(mockSetRegionPrefCookie).toHaveBeenCalledTimes(1);
      expect(setHrefSpy).toHaveBeenCalledTimes(1);
      expect(setHrefSpy).toHaveBeenCalledWith('/mock-target-url');

      // The actual assertion: not just "both happened", but that the cookie write's call index
      // precedes the navigation assignment's call index. See this file's own red-then-green
      // verification, recorded in the SFCC-831/689 build report for this step.
      const cookieWriteOrder = mockSetRegionPrefCookie.mock.invocationCallOrder[0];
      const navigateOrder = setHrefSpy.mock.invocationCallOrder[0];
      expect(cookieWriteOrder).toBeLessThan(navigateOrder);
    });

    test('preserves an already-set sibling cookie field when writing the suppression timestamp', async () => {
      mockShouldShowLanguagePrompt.mockReturnValue({ show: true, targetLanguage: 'fr' });
      mockGetRegionPrefCookie.mockReturnValue({ countrySuppressedAt: 555 });
      stubLocationHref();

      render(<ZimmLanguagePrompt site={SITE} locale={LOCALE} buildUrl={BUILD_URL} />);
      await userEvent.click(screen.getByRole('button', { name: 'mock-switch' }));

      expect(mockSetRegionPrefCookie).toHaveBeenCalledWith(
        expect.objectContaining({ countrySuppressedAt: 555, languageSuppressedAt: expect.any(Number) }),
      );
    });

    test('calls crossSiteUrl with the target alias/locale and the real buildUrl, then navigates to its result', async () => {
      mockShouldShowLanguagePrompt.mockReturnValue({ show: true, targetLanguage: 'it' });
      const setHrefSpy = stubLocationHref();

      render(<ZimmLanguagePrompt site={SITE} locale={LOCALE} buildUrl={BUILD_URL} />);
      await userEvent.click(screen.getByRole('button', { name: 'mock-switch' }));

      expect(mockCrossSiteUrl).toHaveBeenCalledWith('it-eu', 'it', BUILD_URL);
      expect(setHrefSpy).toHaveBeenCalledWith('/mock-target-url');
    });
  });

  describe('onDismiss', () => {
    test('writes the suppression cookie and closes, without navigating', async () => {
      mockShouldShowLanguagePrompt.mockReturnValue({ show: true, targetLanguage: 'fr' });
      const setHrefSpy = stubLocationHref();

      render(<ZimmLanguagePrompt site={SITE} locale={LOCALE} buildUrl={BUILD_URL} />);
      await userEvent.click(screen.getByRole('button', { name: 'mock-dismiss' }));

      expect(mockSetRegionPrefCookie).toHaveBeenCalledTimes(1);
      expect(mockSetRegionPrefCookie).toHaveBeenCalledWith(
        expect.objectContaining({ languageSuppressedAt: expect.any(Number) }),
      );
      expect(setHrefSpy).not.toHaveBeenCalled();
      expect(mockCrossSiteUrl).not.toHaveBeenCalled();
      expect(screen.queryByTestId('mock-prompt')).not.toBeInTheDocument();
    });
  });

  test('EU_LANGUAGE_CONFIG keys exactly match SUPPORTED_EU_LANGUAGES (drift guard)', () => {
    expect(Object.keys(EU_LANGUAGE_CONFIG).sort()).toEqual([...SUPPORTED_EU_LANGUAGES].sort());
  });
});

