68	import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
69	import { useCurrentCustomer } from '@salesforce/retail-react-app/app/hooks/use-current-customer';
70	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
71	import { useStoreLocatorModal } from '@salesforce/retail-react-app/app/hooks/use-store-locator';
72	import { useUpdateShopperContext } from '@salesforce/retail-react-app/app/hooks/use-update-shopper-context';
73	
74	// HOCs
75	import { withCommerceSdkReact } from '@salesforce/retail-react-app/app/components/with-commerce-sdk-react/with-commerce-sdk-react';
76	
77	import { PageDesignerProvider } from '@salesforce/commerce-sdk-react/page-designer';
78	import PageDesignerInit from '@salesforce/retail-react-app/app/components/page-designer-init';
79	
80	// Localization
81	import { IntlProvider } from 'react-intl';
82	
83	// Others
84	import {
85	  CAT_MENU_DEFAULT_NAV_SSR_DEPTH,
86	  CAT_MENU_DEFAULT_ROOT_CATEGORY,
87	  DEFAULT_LOCALE,
88	  DEFAULT_SITE_TITLE,
89	  HOME_HREF,
90	  STORE_LOCATOR_IS_ENABLED,
91	  THEME_COLOR,
92	} from '@salesforce/retail-react-app/app/constants';
93	import { fetchTranslations, getTargetLocale } from '@salesforce/retail-react-app/app/utils/locale';
94	import { flatten, isServer, watchOnlineStatus } from '@salesforce/retail-react-app/app/utils/utils';
95	
96	import Seo from '@salesforce/retail-react-app/app/components/seo';
97	import ShopperAgent from '@salesforce/retail-react-app/app/components/shopper-agent';
98	import { initializeRegistry } from '@salesforce/retail-react-app/app/page-designer/registry';
99	
100	// Initialize registry synchronously at module load time so components are available during SSR
101	initializeRegistry();
102	import { getCommerceAgentConfig } from '@salesforce/retail-react-app/app/utils/config-utils';
103	import { getPathWithLocale } from '@salesforce/retail-react-app/app/utils/url';
104	import { useShopperAgent } from '@salesforce/retail-react-app/app/hooks/use-shopper-agent';
105	
106	type AppProps = {
107	  children: React.ReactNode;
108	};
109	
110	type CategoryNode = {
111	  id: string;
112	  categories?: Record<string, CategoryNode>;
113	  [key: string]: unknown;
114	};
115	
116	const PlaceholderComponent = (): React.ReactElement => (
117	  <Center p="2">
118	    <Spinner size="lg" />
119	  </Center>
120	);
121	
122	const DrawerMenuItemWithData = withCommerceSdkReact(
123	  // any: withCommerceSdkReact's injected item-component props aren't typed upstream;
124	  // narrowing here would require re-deriving withCommerceSdkReact's own generic shape,
125	  // out of scope for a copy-first port.
126	  ({ itemComponent: ItemComponent, data, ...rest }: any) => (
127	    <Fade in={true}>
128	      <ItemComponent {...rest} item={data} itemComponent={DrawerMenuItemWithData} />
129	    </Fade>
130	  ),
131	  {
132	    hook: useCategory,
133	    queryOptions: ({ item }: { item: { id: string } }) => ({
134	      parameters: {
135	        id: item.id,
136	      },
137	    }),
138	    placeholder: PlaceholderComponent,
139	  },
140	);
141	
142	const ListMenuContentWithData = withCommerceSdkReact(
143	  // any: same as DrawerMenuItemWithData above.
144	  ({ data, ...rest }: any) => (
145	    <Fade in={true}>
146	      <ListMenuContent {...rest} item={data} />
147	    </Fade>
148	  ),
149	  {
150	    hook: useCategory,
151	    queryOptions: ({ item }: { item: { id: string } }) => ({
152	      parameters: {
153	        id: item.id,
154	        levels: 2,
155	      },
156	    }),
157	    placeholder: PlaceholderComponent,
158	  },
159	);
160	
161	const App = ({ children }: AppProps): React.ReactElement => {
162	  const { data: categoriesTree } = useCategory({
163	    parameters: { id: CAT_MENU_DEFAULT_ROOT_CATEGORY, levels: CAT_MENU_DEFAULT_NAV_SSR_DEPTH },
164	  });
165	  const categories = flatten((categoriesTree || {}) as CategoryNode, 'categories');
166	  const { getTokenWhenReady } = useAccessToken();
167	  const { usid } = useUsid();
168	  const appOrigin = useAppOrigin();
169	  const activeData = useActiveData();
170	  const history = useHistory();
171	  const location = useLocation();
172	  const authModal = useAuthModal();
173	  const { site, locale, buildUrl } = useMultiSite();
174	  const {
175	    isOpen: isStoreLocatorOpen,
176	    onOpen: onOpenStoreLocator,
177	    onClose: onCloseStoreLocator,
178	  } = useStoreLocatorModal();
179	  const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
180	  const { req } = useServerContext();
181	
182	  const [isOnline, setIsOnline] = useState(true);
183	  const styles = useStyleConfig('App');
184	  const { isOpen, onOpen, onClose } = useDisclosure();
185	
186	  // Determine Page Designer mode from URL - use req for server-side detection
187	  const pageDesignerMode = useMemo(() => {
188	    const queryParams = location?.search || '';
189	    if (queryParams.includes('mode=EDIT')) return 'EDIT';
190	    else if (queryParams.includes('mode=PREVIEW')) return 'PREVIEW';
191	    return undefined;
192	    // matches upstream base _app exactly.
193	  }, [req?.url]);
194	
195	  const targetLocale = getTargetLocale({
196	    getUserPreferredLocales: () => {
197	      // CONFIG: This function should return an array of preferred locales. They can be
198	      // derived from various sources. Below are some examples of those:
199	      //
200	      // - client side: window.navigator.languages
201	      // - the page URL they're on (example.com/en-GB/home)
202	      // - cookie (if their previous preference is saved there)
203	      //
204	      // If this function returns an empty array (e.g. there isn't locale in the page url),
205	      // then the app would use the default locale as the fallback.
206	
207	      // NOTE: Your implementation may differ, this is just what we did.
208	      return [locale?.id || DEFAULT_LOCALE];
209	    },
210	    l10nConfig: site.l10n,
211	  });
212	
213	  // If the translation file exists, it'll be served directly from static folder (and won't reach this code here).
214	  // However, if the file is missing, the App would render a 404 page.
215	  const is404ForMissingTranslationFile = /\/static\/translations\/compiled\/[^.]+\.json$/.test(location?.pathname);
216	
217	  // Fetch the translation message data using the target locale.
218	  const { data: messages } = useQuery({
219	    queryKey: ['app', 'translations', 'messages', targetLocale],
220	    queryFn: () => {
221	      if (is404ForMissingTranslationFile) {
222	        // Return early to prevent an infinite loop
223	        // Otherwise, it'll continue to fetch the missing translation file again
224	        return {};
225	      }
226	      return fetchTranslations(targetLocale, appOrigin);
227	    },
228	    enabled: isServer,
229	  });
230	
231	  // Used to conditionally render header/footer for checkout page
232	  const isCheckout = /\/checkout$/.test(location?.pathname);
233	
234	  const { l10n } = site;
235	  // Get the current currency to be used through out the app
236	  const currency = locale.preferredCurrency || l10n.defaultCurrency;
237	
238	  // Handle creating a new basket if there isn't one already assigned to the current
239	  // customer.
240	  const { data: customer } = useCurrentCustomer();
241	  const { data: basket, dataUpdatedAt: basketQueryLastUpdateTime } = useCurrentBasket();
242	  const config = getConfig();
243	
244	  const updateBasket = useShopperBasketsMutation('updateBasket');
245	  const updateCustomerForBasket = useShopperBasketsMutation('updateCustomerForBasket');
246	
247	  useEffect(() => {
248	    // update the basket currency if it doesn't match the current locale currency
249	    if (basket?.currency && basket?.currency !== currency) {
250	      updateBasket.mutate({
251	        parameters: { basketId: basket.basketId },
252	        body: { currency },
253	      });
254	    }
255	    // matches upstream base _app exactly.
256	  }, [basket?.currency]);
257	
258	  const commerceAgentConfiguration = useMemo(() => {
259	    return getCommerceAgentConfig();
260	    // matches upstream base _app exactly.
261	  }, [config.app.commerceAgent]);
262	
263	  useEffect(() => {
264	    // update the basket customer email
265	    if (basket && customer?.isRegistered && customer?.email && customer?.email !== basket?.customerInfo?.email) {
266	      updateCustomerForBasket.mutate({
267	        parameters: { basketId: basket.basketId },
268	        body: {
269	          email: customer.email,
270	        },
271	      });
272	    }
273	    // matches upstream base _app exactly.
274	  }, [customer?.isRegistered, customer?.email, basket?.customerInfo?.email]);
275	
276	  useEffect(() => {
277	    // Listen for online status changes.
278	    watchOnlineStatus((online: boolean) => {
279	      setIsOnline(online);
280	    });
281	  }, []);
282	
283	  // Handle updating the shopper context
284	  useUpdateShopperContext();
285	
286	  useEffect(() => {
287	    // Lets automatically close the mobile navigation when the
288	    // location path is changed.
289	    onClose();
290	    // matches upstream base _app exactly.
291	  }, [location]);
292	
293	  // SFCC-885: the mobile drawer's isOpen state above is otherwise only ever closed by route
294	  // changes (the effect above) or an explicit close control — nothing closes it on a resize or
295	  // orientation change. That's a real gap, not a hardening: DrawerMenu renders a Chakra
296	  // <Drawer>, which always portals its content straight to document.body, so HideOnDesktop's
297	  // display:none on its wrapper (below) never actually hides an already-open drawer once the
298	  // viewport crosses into desktop width — the drawer keeps rendering full-screen on top of the
299	  // now-visible desktop nav. Closing it here whenever the viewport is no longer mobile (same
300	  // MOBILE_DESKTOP_SPLIT the HideOnDesktop/HideOnMobile split below already uses) fixes that for
301	  // every way the crossing can happen, not just a device rotation.
302	  const isMobileViewport = useBreakpointValue({ base: true, [MOBILE_DESKTOP_SPLIT]: false });
303	  useEffect(() => {
304	    if (isMobileViewport === false) onClose();
305	  }, [isMobileViewport]);
306	
307	  const onLogoClick = (): void => {
308	    // Goto the home page.
309	    const path = buildUrl(HOME_HREF);
310	
311	    history.push(path);
312	
313	    // Close the drawer.
314	    onClose();
315	  };
316	
317	  const onCartClick = (): void => {
318	    const path = buildUrl('/cart');
319	    history.push(path);
320	
321	    // Close the drawer.
322	    onClose();
323	  };
324	
325	  const onAccountClick = (): void => {
326	    // Link to account page if registered; Header component will show auth modal for guest users
327	    const path = buildUrl('/account');
328	    history.push(path);
329	  };
330	
331	  const onWishlistClick = (): void => {
332	    // Link to wishlist page if registered; Header component will show auth modal for guest users
333	    const path = buildUrl('/account/wishlist');
334	    history.push(path);
335	  };
336	
337	  const { actions: shopperAgentActions } = useShopperAgent();
338	
339	  const trackPage = (): void => {
340	    activeData.trackPage(site.id, locale.id, currency);
341	  };
342	
343	  useEffect(() => {
344	    trackPage();
345	    // matches upstream base _app exactly.
346	  }, [location]);
347	
348	  const getHrefForLocale = (localeId: string): string =>
349	    `${appOrigin}${getRouterBasePath()}${getPathWithLocale(localeId, buildUrl, {
350	      location: { ...location, search: '' },
351	    })}`;
352	
353	  return (
354	    <Box className="sf-app" {...styles.container}>
355	      <StorefrontPreview getToken={getTokenWhenReady} getBasePath={getRouterBasePath}>
356	        <IntlProvider
357	          onError={(err) => {
358	            if (!messages) {
359	              // During the ssr prepass phase the messages object has not loaded, so we can suppress
360	              // errors during this time.
361	              return;
362	            }
363	            if (err.code === 'MISSING_TRANSLATION') {
364	              // NOTE: Remove the console error for missing translations during development,
365	              // as we knew translations would be added later.
366	              logger.warn('Missing translation', {
367	                namespace: 'App.IntlProvider',
368	                additionalProperties: {
369	                  errorMessage: err.message,
370	                },
371	              });
372	              return;
373	            }
374	            throw err;
375	          }}
376	          locale={targetLocale}
377	          messages={messages}
378	          // For react-intl, the _default locale_ refers to the locale that the inline `defaultMessage`s are written for.
379	          // NOTE: if you update this value, please also update the following npm scripts in `template-retail-react-app/package.json`:
380	          // - "extract-default-translations"
381	          // - "compile-translations:pseudo"
382	          defaultLocale={DEFAULT_LOCALE}
383	        >
384	          <CurrencyProvider currency={currency}>
385	            <Seo>
386	              <meta name="theme-color" content={THEME_COLOR} />
387	              <meta name="apple-mobile-web-app-title" content={DEFAULT_SITE_TITLE} />
388	              <link rel="apple-touch-icon" href={getAssetUrl('static/img/global/apple-touch-icon.png')} />
389	              <link rel="manifest" href={getAssetUrl('static/manifest.json')} />
390	
391	              {/* Urls for all localized versions of this page (including current page)
392	              For more details on hrefLang, see https://developers.google.com/search/docs/advanced/crawling/localized-versions */}
393	              {site.l10n?.supportedLocales.map((l: { id: string }) => (
394	                <link rel="alternate" hrefLang={l.id.toLowerCase()} href={getHrefForLocale(l.id)} key={l.id} />
395	              ))}
396	              {/* A general locale as fallback. For example: "en" if default locale is "en-GB" */}
397	              <link rel="alternate" hrefLang={site.l10n.defaultLocale.slice(0, 2)} href={getHrefForLocale(locale.id)} />
398	              {/* A wider fallback for user locales that the app does not support */}
399	              <link rel="alternate" hrefLang="x-default" href={`${appOrigin}/`} />
400	            </Seo>
401	
402	            {commerceAgentConfiguration?.enabled === 'true' && (
403	              <ShopperAgent
404	                commerceAgentConfiguration={commerceAgentConfiguration}
405	                basketDoneLoading={basketQueryLastUpdateTime > 0}
406	              />
407	            )}
408	
409	            <ScrollToTop />
410	
411	            <Box id="app" display="flex" flexDirection="column" flex={1}>
412	              <SkipNavLink zIndex="skipLink">Skip to Content</SkipNavLink>
413	              {storeLocatorEnabled && <StoreLocatorModal isOpen={isStoreLocatorOpen} onClose={onCloseStoreLocator} />}
414	              <Island hydrateOn={'visible'}>
415	                <Box {...styles.headerWrapper}>
416	                  {!isCheckout ? (
417	                    <>
418	                      <AboveHeader />
419	                      <Header
420	                        onMenuClick={onOpen}
421	                        onLogoClick={onLogoClick}
422	                        onMyCartClick={onCartClick}
423	                        onMyAccountClick={onAccountClick}
424	                        onWishlistClick={onWishlistClick}
425	                        onStoreLocatorClick={onOpenStoreLocator}
426	                        onAgentClick={shopperAgentActions.open}
427	                      >
428	                        <HideOnDesktop>
429	                          <DrawerMenu
430	                            isOpen={isOpen}
431	                            onClose={onClose}
432	                            onLogoClick={onLogoClick}
433	                            root={categories?.[CAT_MENU_DEFAULT_ROOT_CATEGORY]}
434	                            itemsKey="categories"
435	                            itemsCountKey="onlineSubCategoriesCount"
436	                            itemComponent={DrawerMenuItemWithData}
437	                          />
438	                        </HideOnDesktop>
439	
440	                        <HideOnMobile>
441	                          <ListMenu
442	                            root={categories?.[CAT_MENU_DEFAULT_ROOT_CATEGORY]}
443	                            itemsKey="categories"
444	                            itemsCountKey="onlineSubCategoriesCount"
445	                            contentComponent={ListMenuContentWithData}
446	                          />
447	                        </HideOnMobile>
448	                      </Header>
449	                    </>
450	                  ) : (
451	                    <CheckoutHeader />
452	                  )}
453	                </Box>
454	              </Island>
455	              {!isOnline && <OfflineBanner />}
456	              <AddToCartModalProvider>
457	                <BonusProductSelectionModalProvider>
458	                  <SkipNavContent
459	                    style={{
460	                      display: 'flex',
461	                      flexDirection: 'column',
462	                      flex: 1,
463	                      outline: 0,
464	                    }}
465	                  >
466	                    <Box as="main" id="app-main" role="main" display="flex" flexDirection="column" flex="1">
467	                      <OfflineBoundary isOnline={false}>
468	                        <PageDesignerProvider
469	                          clientId="pwa-kit-client"
470	                          targetOrigin="*"
471	                          usid={usid ?? undefined}
472	                          mode={pageDesignerMode}
473	                        >
474	                          <PageDesignerInit />
475	                          {children}
476	                        </PageDesignerProvider>
477	                      </OfflineBoundary>
478	                    </Box>
479	                  </SkipNavContent>
480	
481	                  <Island hydrateOn={'visible'}>{!isCheckout ? <Footer /> : <CheckoutFooter />}</Island>
482	
483	                  <AuthModal {...authModal} />
484	                  <ZimmLanguagePrompt site={site} locale={locale} buildUrl={buildUrl} />
485	                </BonusProductSelectionModalProvider>
486	              </AddToCartModalProvider>
487	            </Box>
488	          </CurrencyProvider>
489	        </IntlProvider>
490	      </StorefrontPreview>
491	    </Box>
492	  );
493	};
494	
495	export default App;
496

