import React, { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { ZimmCountryLanguageMismatch } from './index';

const meta: Meta<typeof ZimmCountryLanguageMismatch> = {
  title: 'Layout/ZimmCountryLanguageMismatch',
  component: ZimmCountryLanguageMismatch,
};
export default meta;
type Story = StoryObj<typeof ZimmCountryLanguageMismatch>;

// Both stories below are purely visual — no `play` function. The callback-wiring and
// copy-branch-per-variant behaviour that a `play` would otherwise assert is already covered,
// more precisely (exact `target` echo-back, onDismiss firing on every close path), by this
// component's own index.test.tsx — see .claude/rules/testing.md's "do not duplicate coverage
// across layers" note.

// Named component, not an inline `render: () => { useState(...) }` — see zimmDrawer's own story
// for why a lowercase `render` can't call hooks directly.
const LocationExample = () => {
  const [isOpen, setIsOpen] = useState(true);
  return (
    <ZimmCountryLanguageMismatch
      variant="location"
      isOpen={isOpen}
      onDismiss={() => setIsOpen(false)}
      inCountry="in Germany"
      currentStore="Zimmermann Australia"
      targetStore="Zimmermann Germany"
      target="ZimmermannEUde"
      onRedirect={() => setIsOpen(false)}
    />
  );
};

export const Location: Story = {
  render: () => <LocationExample />,
};

const LanguageExample = () => {
  const [isOpen, setIsOpen] = useState(true);
  return (
    <ZimmCountryLanguageMismatch
      variant="language"
      isOpen={isOpen}
      onDismiss={() => setIsOpen(false)}
      inCountry="in France"
      inLanguage="in French"
      inCurrentLanguage="in English"
      target="fr"
      onSwitchLanguage={() => setIsOpen(false)}
    />
  );
};

export const Language: Story = {
  render: () => <LanguageExample />,
};

// --- Confirmed 2026-09-14 (Marcel) after visual review of all four cases below — wired into
// real use at zimmLanguagePrompt/index.tsx's EU_LANGUAGE_CONFIG map. These four props values are
// hand-typed to match that map's real output, not re-imported from it, so this story keeps
// demonstrating the real, current mapping even if that file changes shape later — a drift here
// is a visible story regression, not a silent divergence.

const LanguageDetectedExample = ({
  inCountry,
  inLanguage,
  inCurrentLanguage,
  target,
}: {
  inCountry: string;
  inLanguage: string;
  inCurrentLanguage: string;
  target: string;
}) => {
  const [isOpen, setIsOpen] = useState(true);
  return (
    <ZimmCountryLanguageMismatch
      variant="language"
      isOpen={isOpen}
      onDismiss={() => setIsOpen(false)}
      inCountry={inCountry}
      inLanguage={inLanguage}
      inCurrentLanguage={inCurrentLanguage}
      target={target}
      onSwitchLanguage={() => setIsOpen(false)}
    />
  );
};

/** Shopper on the English EU site, browser reports Italian. */
export const LanguageDetectedItalian: Story = {
  render: () => (
    <LanguageDetectedExample inCountry="in Italy" inLanguage="in Italian" inCurrentLanguage="in English" target="it" />
  ),
};

/** Shopper on the English EU site, browser reports Spanish. */
export const LanguageDetectedSpanish: Story = {
  render: () => (
    <LanguageDetectedExample inCountry="in Spain" inLanguage="in Spanish" inCurrentLanguage="in English" target="es" />
  ),
};

/**
 * Shopper on the French EU site, browser reports English — the one case with no clean
 * language-to-country mapping (English isn't the home language of one obvious EU country the
 * way French/Italian/Spanish are). "Ireland" was chosen over "the UK" specifically because
 * Zimmermann already has a separate, real UK storefront (ZimmermannUK, /uk/) that en-eu is NOT
 * — naming the UK here would contradict the site's own architecture, not just be geographically
 * approximate. This is the story most worth scrutinising before committing to the map.
 */
export const LanguageDetectedEnglish: Story = {
  render: () => (
    <LanguageDetectedExample
      inCountry="in Ireland"
      inLanguage="in English"
      inCurrentLanguage="in French"
      target="en"
    />
  ),
};

